﻿/**
 * 代码指南：
 * 文件：pages/Index.ets
 * 用途：带浮动底部导航的应用外壳。
 * 何时修改：切换顶级页面或导航行为时。
 * 相关文件：pages/page1/*、pages/page2/*、pages/page3/*、pages/page4/*。
 */
import { Page1View } from './page1/Page1View'
import { Page2View } from './page2/Page2View'
import { Page3View } from './page3/Page3View'
import { Page4View } from './page4/Page4View'
import { Page1Theme } from './page1/Page1Theme'
import { page2Coordinator } from './page2/Page2Coordinator'
import { page1Store } from './page1/app/Page1UiStore'
import fs from '@ohos.file.fs'
import util from '@ohos.util'
import { bengkuiMasterError, bengkuiMasterErrText } from '../utils/BengkuiMasterLogger'

const PAGE4_PLACE_BINDING_FILE: string = 'page4_place_bindings.json'
const SPLASH_SLOGAN: string = '为让物流运输更高效，更安全，更智能，让每一次物流运输都智行无忧'
interface Page4PlaceBindingPayload {
  homeNodeId?: string
  companyNodeId?: string
}

@Entry
@Component
struct Index {
  @State private currentIndex: number = 0
  @State private showFloatingNav: boolean = false
  @State private showSplash: boolean = true
  @State private splashScale: number = 0.86
  @State private splashTextLen: number = 0
  private splashTimerId: number = -1
  private splashAnimTimerId: number = -1
  private splashTextTimerId: number = -1
  private splashHardTimeoutId: number = -1

  aboutToAppear(): void {
    try {
      this.restorePlaceConfiguredOnAppEnter()
    } catch (e) {
      bengkuiMasterError('Index.aboutToAppear.restorePlaceConfiguredOnAppEnter', e)
    }
    // Page2 识别链路需要在非 Page2 页面也持续工作；入口页先以后台低频模式拉起。
    try {
      page2Coordinator.enterBackgroundMode()
    } catch (e) {
      bengkuiMasterError('Index.aboutToAppear.page2Coordinator.enterBackgroundMode', e)
    }
    void page2Coordinator.start()
      .catch((e: Object): void => {
        bengkuiMasterError('Index.aboutToAppear.page2Coordinator.start', e)
      })
    this.clearSplashTimer()
    this.clearSplashAnimTimer()
    this.clearSplashTextTimer()
    this.clearSplashHardTimeout()
    this.showSplash = true
    this.splashScale = 0.86
    this.splashTextLen = 0
    this.splashAnimTimerId = setTimeout((): void => {
      this.splashAnimTimerId = -1
      this.splashScale = 1
    }, 30) as number
    this.splashTextTimerId = setInterval((): void => {
      if (this.splashTextLen >= SPLASH_SLOGAN.length) {
        this.clearSplashTextTimer()
        this.armSplashExit(1000)
        return
      }
      this.splashTextLen += 1
      if (this.splashTextLen >= SPLASH_SLOGAN.length) {
        this.clearSplashTextTimer()
        this.armSplashExit(1000)
      }
    }, 40) as number
    // 兜底：避免极低概率定时器未触发导致开屏长时间停留。
    this.splashHardTimeoutId = setTimeout((): void => {
      this.splashHardTimeoutId = -1
      if (!this.showSplash) return
      this.clearSplashTimer()
      this.clearSplashTextTimer()
      this.clearSplashAnimTimer()
      this.showSplash = false
    }, 6500) as number
  }

  aboutToDisappear(): void {
    this.clearSplashTimer()
    this.clearSplashAnimTimer()
    this.clearSplashTextTimer()
    this.clearSplashHardTimeout()
  }

  private restorePlaceConfiguredOnAppEnter(): void {
    let home: string = ''
    let company: string = ''
    let f: fs.File | undefined = undefined
    try {
      const bindingPath: string = `${getContext(this).filesDir}/${PAGE4_PLACE_BINDING_FILE}`
      f = fs.openSync(bindingPath, fs.OpenMode.READ_ONLY)
      const st: fs.Stat = fs.statSync(bindingPath)
      const size: number = Number(st.size)
      if (Number.isFinite(size) && size > 0 && size <= 4096) {
        const buf: ArrayBuffer = new ArrayBuffer(Math.trunc(size))
        const readLen: number = fs.readSync(f.fd, buf)
        if (readLen > 0) {
          const bytes: Uint8Array = new Uint8Array(buf, 0, readLen)
          const txt: string = new util.TextDecoder('utf-8', { ignoreBOM: true }).decodeWithStream(bytes, { stream: false })
          const parsed: Page4PlaceBindingPayload = JSON.parse(txt) as Page4PlaceBindingPayload
          home = String(parsed.homeNodeId ?? '').trim().toUpperCase()
          company = String(parsed.companyNodeId ?? '').trim().toUpperCase()
        }
      }
    } catch (e) {
      home = ''
      company = ''
      const msg: string = this.errText(e).toLowerCase()
      const notFound: boolean =
        msg.indexOf('no such file or directory') >= 0 ||
        msg.indexOf('enoent') >= 0 ||
        msg.indexOf('file not found') >= 0
      if (!notFound) {
        bengkuiMasterError(
          'Index.restorePlaceConfiguredOnAppEnter',
          e,
          `bindingPath=${getContext(this).filesDir}/${PAGE4_PLACE_BINDING_FILE}`
        )
      }
    } finally {
      if (f) {
        try { fs.closeSync(f.fd) } catch (_) {}
      }
    }
    page1Store.setPlaceConfigured(home, company)
  }

  build() {
    Stack({ alignContent: Alignment.Bottom }) {
      if (!this.showSplash) {
        this.buildCurrentPage()

        if (this.showFloatingNav) {
          this.buildNavPanel()
        }
      }

      if (this.showSplash) {
        Stack() {
          Column({ space: 18 }) {
            Image($rawfile('开屏画面.png'))
              .width('68%')
              .height('58%')
              .objectFit(ImageFit.Contain)
              .scale({ x: this.splashScale, y: this.splashScale })
              .animation({ duration: 2000, curve: Curve.EaseOut })

            Text(this.splashSloganPreview())
              .width('90%')
              .fontSize(18)
              .fontWeight(FontWeight.Medium)
              .fontColor('#1F2937')
              .textAlign(TextAlign.Center)
              .maxLines(2)
          }
          .width('100%')
          .height('100%')
          .justifyContent(FlexAlign.Center)
          .translate({ x: 0, y: -56 })
        }
        .width('100%')
        .height('100%')
        .backgroundColor('#FFFFFF')
        .zIndex(999)
        .onClick((): void => {
          this.skipSplashNow()
        })
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Page1Theme.BG)
    .onClick((): void => {
      if (this.showSplash) return
      this.showFloatingNav = !this.showFloatingNav
    })
  }

  private armSplashExit(delayMs: number): void {
    if (!this.showSplash) return
    this.clearSplashTimer()
    this.splashTimerId = setTimeout((): void => {
      this.splashTimerId = -1
      this.showSplash = false
    }, Math.max(0, Math.trunc(delayMs))) as number
  }

  private skipSplashNow(): void {
    if (!this.showSplash) return
    this.clearSplashTimer()
    this.clearSplashTextTimer()
    this.clearSplashAnimTimer()
    this.clearSplashHardTimeout()
    this.showSplash = false
  }

  private clearSplashTimer(): void {
    if (this.splashTimerId >= 0) {
      clearTimeout(this.splashTimerId)
      this.splashTimerId = -1
    }
  }

  private clearSplashAnimTimer(): void {
    if (this.splashAnimTimerId >= 0) {
      clearTimeout(this.splashAnimTimerId)
      this.splashAnimTimerId = -1
    }
  }

  private clearSplashTextTimer(): void {
    if (this.splashTextTimerId >= 0) {
      clearInterval(this.splashTextTimerId)
      this.splashTextTimerId = -1
    }
  }

  private clearSplashHardTimeout(): void {
    if (this.splashHardTimeoutId >= 0) {
      clearTimeout(this.splashHardTimeoutId)
      this.splashHardTimeoutId = -1
    }
  }

  private splashSloganPreview(): string {
    const len: number = this.splashTextLen
    if (len <= 0) return ''
    if (len >= SPLASH_SLOGAN.length) return SPLASH_SLOGAN
    return SPLASH_SLOGAN.substring(0, len)
  }

  private errText(e: Object): string {
    return bengkuiMasterErrText(e)
  }

  @Builder
  private buildCurrentPage(): void {
    if (this.currentIndex === 0) {
      Page1View()
    } else if (this.currentIndex === 1) {
      Page2View()
    } else if (this.currentIndex === 2) {
      Page3View()
    } else {
      Page4View()
    }
  }

  @Builder
  private buildNavPanel(): void {
    Row() {
      Row({ space: 80 }) {
        this.navItem('地图', 0)
        this.navItem('视频', 1)
        this.navItem('3D', 2)
        this.navItem('助手', 3)
      }
      .padding({ left: 80, right: 80, top: 14, bottom: 14 })
      .borderRadius(32)
      .backgroundColor('#4DFFFFFF')
      .backgroundBlurStyle(BlurStyle.Thin)
      .backdropBlur(40)
      .shadow({ radius: 40, color: '#00000012', offsetX: 0, offsetY: 12 })
    }
    .width('100%')
    .justifyContent(FlexAlign.Center)
    .margin({ bottom: 44 })
    .transition({ type: TransitionType.All, opacity: 0, scale: { x: 0.95, y: 0.95 } })
    .onClick((): void => {}) // 拦截点击事件
  }

  @Builder
  private navItem(label: string, index: number): void {
    Column({ space: 4 }) {
      Stack({ alignContent: Alignment.Center }) {
        if (index === 0) {
          Image(this.currentIndex === index ? $rawfile('icon/地图.png') : $rawfile('icon/地图未选择.png'))
            .width(26)
            .height(26)
            .translate({ x: 0, y: this.currentIndex === index ? -4 : 0 })
            .animation({ duration: 220, curve: Curve.EaseOut })
        } else if (index === 1) {
          Image(this.currentIndex === index ? $rawfile('icon/视频.png') : $rawfile('icon/视频未选择.png'))
            .width(26)
            .height(26)
            .translate({ x: 0, y: this.currentIndex === index ? -4 : 0 })
            .animation({ duration: 220, curve: Curve.EaseOut })
        } else if (index === 2) {
          Image(this.currentIndex === index ? $rawfile('icon/3d.png') : $rawfile('icon/3d未选择.png'))
            .width(26)
            .height(26)
            .translate({ x: 0, y: this.currentIndex === index ? -4 : 0 })
            .animation({ duration: 220, curve: Curve.EaseOut })
        } else {
          Image(this.currentIndex === index ? $rawfile('icon/智能体.png') : $rawfile('icon/智能体未选择.png'))
            .width(26)
            .height(26)
            .translate({ x: 0, y: this.currentIndex === index ? -4 : 0 })
            .animation({ duration: 220, curve: Curve.EaseOut })
        }
      }
      .width(44)
      .height(44)

      Text(label)
        .fontSize(12)
        .fontWeight(this.currentIndex === index ? FontWeight.Bold : FontWeight.Medium)
        .fontColor(this.currentIndex === index ? Page1Theme.VIOLET_PRIMARY : Page1Theme.TEXT_SECONDARY)
        .opacity(this.currentIndex === index ? 1.0 : 0.6)
    }
    .onClick((): void => {
      animateTo({ duration: 300, curve: Curve.EaseOut }, (): void => {
        this.currentIndex = index
      })
    })
  }
}

import { Page1Action } from '../../page1/types/Page1Types'
import { Page4PlannedTask } from '../modules/Page4OpenClawPlanQaModule'

export interface Page4TaskParseDeps {
  extractDestNode: (text: string) => string
  isValidGridId: (id: string) => boolean
  resolveActionByText: (lower: string) => Page1Action | undefined
  looksLikeCaptureFrameIntent: (lower: string) => boolean
  containsAny: (text: string, keys: Array<string>) => boolean
}

export class Page4OrchestrationLayer {
  static actionName(action: Page1Action): string {
    if (action === Page1Action.GO) return '前进'
    if (action === Page1Action.BACK) return '后退'
    if (action === Page1Action.LEFT) return '左转'
    if (action === Page1Action.RIGHT) return '右转'
    if (action === Page1Action.UTURN) return '掉头'
    if (action === Page1Action.STOP) return '停止'
    if (action === Page1Action.SCRAM) return '紧急停止'
    if (action === Page1Action.TFTA) return 'TFTA'
    return '动作'
  }

  static resolveActionByText(
    textLower: string,
    lastAction: Page1Action | undefined,
    containsAny: (text: string, keys: Array<string>) => boolean
  ): Page1Action | undefined {
    if (containsAny(textLower, ['再来一次', '重复上一动作', '继续刚才动作', 'repeat'])) return lastAction
    if (containsAny(textLower, ['紧急停止', '急停', 'scram'])) return Page1Action.SCRAM
    if (containsAny(textLower, ['停止', '停车', 'stop'])) return Page1Action.STOP
    if (containsAny(textLower, ['前进', '向前', 'go'])) return Page1Action.GO
    if (containsAny(textLower, ['后退', '倒车', 'back'])) return Page1Action.BACK
    if (containsAny(textLower, ['左转'])) return Page1Action.LEFT
    if (containsAny(textLower, ['右转'])) return Page1Action.RIGHT
    if (containsAny(textLower, ['掉头'])) return Page1Action.UTURN
    return undefined
  }

  static looksLikeCaptureFrameIntent(
    textLower: string,
    containsAny: (text: string, keys: Array<string>) => boolean
  ): boolean {
    return containsAny(textLower, [
      '获取当前摄像头画面',
      '获取当前画面',
      '抓取当前画面',
      '读取当前画面',
      '保存当前画面',
      '给我当前画面',
      '看一下当前画面',
      'camera frame',
      'current frame',
      'capture frame'
    ])
  }

  static splitPromptToClauses(text: string): Array<string> {
    const src: string = text
      .replace(/然后|接着|随后|并且|并且再|同时|接下来|再去|再到/g, '|')
      .replace(/[，,；;。.!！?？\n]/g, '|')
    const raw: Array<string> = src.split('|')
    const out: Array<string> = []
    for (let i: number = 0; i < raw.length; i++) {
      const one: string = raw[i].trim()
      if (one.length > 0) out.push(one)
    }
    return out
  }

  static parseTaskFromClause(clause: string, deps: Page4TaskParseDeps): Page4PlannedTask | undefined {
    const lower: string = clause.toLowerCase()
    const dest: string = deps.extractDestNode(clause)
    if (dest.length > 0 && deps.isValidGridId(dest)) return { kind: 'route', destNodeId: dest }

    const action: Page1Action | undefined = deps.resolveActionByText(lower)
    if (action !== undefined) return { kind: 'action', action: action }

    if (deps.containsAny(lower, ['开启自动跟随', '打开自动跟随', '自动跟随开启', '自动驾驶开启'])) return { kind: 'auto_follow', enabled: true }
    if (deps.containsAny(lower, ['关闭自动跟随', '停止自动跟随', '自动跟随关闭', '自动驾驶关闭'])) return { kind: 'auto_follow', enabled: false }
    if (deps.containsAny(lower, ['开启真车模式', '真车模式', 'real_send'])) return { kind: 'send_mode', mode: 'REAL_SEND' }
    if (deps.containsAny(lower, ['开启仿真模式', '仿真模式', 'dry_run', '关闭真车模式'])) return { kind: 'send_mode', mode: 'DRY_RUN' }
    if (deps.looksLikeCaptureFrameIntent(lower)) return { kind: 'capture_frame' }
    if (deps.containsAny(lower, ['查询状态', '状态', 'status'])) return { kind: 'query_status' }
    if (deps.containsAny(lower, ['识别状态', '视觉状态', '识别结果', 'vision'])) return { kind: 'query_vision' }
    if (deps.containsAny(lower, ['网络', '通信'])) return { kind: 'query_comm' }
    if (deps.containsAny(lower, ['视频', '相机'])) return { kind: 'query_video' }
    return undefined
  }

  static parseLocalPlannedTasks(text: string, deps: Page4TaskParseDeps): Array<Page4PlannedTask> {
    const clauses: Array<string> = this.splitPromptToClauses(text)
    const out: Array<Page4PlannedTask> = []
    for (let i: number = 0; i < clauses.length; i++) {
      const task: Page4PlannedTask | undefined = this.parseTaskFromClause(clauses[i], deps)
      if (!task) continue
      out.push(task)
    }
    return out
  }

  static looksLikeMultiTask(text: string, containsAny: (text: string, keys: Array<string>) => boolean): boolean {
    const x: string = text.trim()
    if (x.length <= 0) return false
    if (this.splitPromptToClauses(x).length >= 2) return true
    return containsAny(x, ['然后', '接着', '并且', '同时', '再', '随后', ';', '；', ',', '，'])
  }

  static looksLikeControlIntent(
    text: string,
    lower: string,
    extractDestNode: (text: string) => string,
    containsAny: (text: string, keys: Array<string>) => boolean
  ): boolean {
    if (text.trim().length <= 0) return false
    if (this.looksLikeMultiTask(text, containsAny)) return true
    if (extractDestNode(text).length > 0) return true
    const keywords: Array<string> = [
      '导航', '前往', '去', '到',
      '返仓', '回仓', '返航', '回基地', '回中心', '回物流中心', '回快递点', '回仓库', '返仓库',
      '前进', '后退', '左转', '右转', '掉头', '停止', '急停', '刹车',
      '自动跟随', '自动驾驶', '真车模式', '仿真模式', 'real_send', 'dry_run',
      '撤销', '回到安全点',
      '抓拍', '截图', '拍照', '相机', '视频',
      '查询状态', '状态', '识别', '视觉', '通信', '网络',
      '读取文件', '读文件', '文件内容', '进程列表', '查询进程', '执行命令', '命令行', 'process', 'read_file', 'exec_cmd'
    ]
    return containsAny(lower, keywords)
  }
}

import {
  buildOpenClawChatCompletionsUrl,
  buildOpenClawGatewayWsUrl,
  buildPcToolGatewayUrl,
  buildTabletCompanionUrl,
  OPENCLAW_CHAT_MODEL,
  PC_TOOL_CONNECT_TIMEOUT_MS,
  PC_TOOL_READ_TIMEOUT_MS,
  TABLET_COMPANION_CONNECT_TIMEOUT_MS,
  TABLET_COMPANION_NODE_ID,
  TABLET_COMPANION_READ_TIMEOUT_MS
} from '../../../config/DeviceNetworkConfig'
import { OpenClawGatewayClient, OpenClawChatMessage } from '../../../services/assistant/OpenClawGatewayClient'
import { OpenClawGatewayWsClient } from '../../../services/assistant/OpenClawGatewayWsClient'
import { PcToolGatewayClient } from '../../../services/assistant/PcToolGatewayClient'
import { TabletCompanionClient } from '../../../services/assistant/TabletCompanionClient'

export interface Page4GatewayState {
  lastGoodOpenClawHost: string
  openClawHostCooldownUntilMs: Record<string, number>
  openClawHostCooldownMs: number
  openClawWsSessionKey?: string
}

export class Page4GatewayLayer {
  static summarizePcToolText(toolName: string, text: string): string {
    const one: string = text.trim()
    if (one.length <= 0) return `pc.${toolName}: (empty)`
    const short: string = one.length > 240 ? `${one.substring(0, 240)}...` : one
    return `pc.${toolName}: ${short}`
  }

  static summarizeTabletCompanionText(action: string, text: string): string {
    const one: string = text.trim()
    if (one.length <= 0) return `tablet.${action}: (empty)`
    const short: string = one.length > 240 ? `${one.substring(0, 240)}...` : one
    return `tablet.${action}: ${short}`
  }

  static normalizeGatewayErrorText(raw: string): string {
    const text: string = raw.trim()
    if (text.length <= 0) return 'unknown'
    if (text.indexOf('ECONNREFUSED') >= 0) return '连接被拒绝'
    if (text.indexOf('ETIMEDOUT') >= 0 || text.indexOf('timeout') >= 0) return '连接超时'
    if (text.indexOf('401') >= 0 || text.indexOf('Unauthorized') >= 0) return '鉴权失败'
    if (text.indexOf('403') >= 0 || text.indexOf('Forbidden') >= 0) return '权限不足'
    return text
  }

  static isOpenClawHostCooling(state: Page4GatewayState, host: string, nowMs: number): boolean {
    const untilMs: number | undefined = state.openClawHostCooldownUntilMs[host]
    return typeof untilMs === 'number' && untilMs > nowMs
  }

  static markOpenClawHostSuccess(state: Page4GatewayState, host: string): Page4GatewayState {
    state.lastGoodOpenClawHost = host
    state.openClawHostCooldownUntilMs[host] = 0
    return state
  }

  static markOpenClawHostFail(state: Page4GatewayState, host: string): Page4GatewayState {
    state.openClawHostCooldownUntilMs[host] = Date.now() + state.openClawHostCooldownMs
    return state
  }

  static rankOpenClawHosts(state: Page4GatewayState, inputHosts: Array<string>): Array<string> {
    const out: Array<string> = []
    const normal: Array<string> = []
    const cooling: Array<string> = []
    const nowMs: number = Date.now()
    const pushUnique = (arr: Array<string>, host: string): void => {
      for (let i: number = 0; i < arr.length; i++) {
        if (arr[i] === host) return
      }
      arr.push(host)
    }

    for (let i: number = 0; i < inputHosts.length; i++) {
      const host: string = inputHosts[i].trim()
      if (host.length <= 0) continue
      if (this.isOpenClawHostCooling(state, host, nowMs)) pushUnique(cooling, host)
      else pushUnique(normal, host)
    }

    const preferred: string = state.lastGoodOpenClawHost.trim()
    if (preferred.length > 0) {
      for (let i: number = 0; i < normal.length; i++) {
        if (normal[i] === preferred) {
          out.push(preferred)
          break
        }
      }
    }

    for (let i: number = 0; i < normal.length; i++) {
      const host: string = normal[i]
      let exists: boolean = false
      for (let j: number = 0; j < out.length; j++) {
        if (out[j] === host) {
          exists = true
          break
        }
      }
      if (!exists) out.push(host)
    }

    for (let i: number = 0; i < cooling.length; i++) out.push(cooling[i])
    return out
  }

  static async callPcToolGateway(
    state: Page4GatewayState,
    toolName: string,
    payload: Record<string, Object | string | number | boolean>,
    hosts: Array<string>,
    tokens: Array<string>
  ): Promise<{ ok: boolean, summary: string, state: Page4GatewayState }> {
    if (hosts.length <= 0) return { ok: false, summary: '未检测到 PC 工具网关主机地址。', state }
    const errs: Array<string> = []
    for (let i: number = 0; i < hosts.length; i++) {
      const host: string = hosts[i]
      for (let k: number = 0; k < tokens.length; k++) {
        const token: string = tokens[k]
        const client: PcToolGatewayClient = new PcToolGatewayClient({
          endpoint: buildPcToolGatewayUrl(host, toolName),
          bearerToken: token,
          connectTimeoutMs: PC_TOOL_CONNECT_TIMEOUT_MS,
          readTimeoutMs: PC_TOOL_READ_TIMEOUT_MS
        })
        const result = await client.call(payload)
        if (result.ok) {
          state = this.markOpenClawHostSuccess(state, host)
          return { ok: true, summary: this.summarizePcToolText(toolName, result.text), state }
        }
        errs.push(`${host}/${k + 1}:${this.normalizeGatewayErrorText(result.errorText)}`)
      }
      state = this.markOpenClawHostFail(state, host)
    }
    const merged: string = errs.length > 0 ? errs.join(' | ') : '请求失败'
    return { ok: false, summary: `pc.${toolName}: ${merged}`, state }
  }

  static async callTabletCompanion(
    state: Page4GatewayState,
    action: string,
    args: Record<string, Object | string | number | boolean>,
    hosts: Array<string>,
    tokens: Array<string>,
    nodeId: string = TABLET_COMPANION_NODE_ID
  ): Promise<{ ok: boolean, summary: string, state: Page4GatewayState }> {
    if (hosts.length <= 0) return { ok: false, summary: '未检测到平板伴侣主机地址。', state }
    const errs: Array<string> = []
    for (let i: number = 0; i < hosts.length; i++) {
      const host: string = hosts[i]
      for (let k: number = 0; k < tokens.length; k++) {
        const token: string = tokens[k]
        const client: TabletCompanionClient = new TabletCompanionClient({
          endpoint: buildTabletCompanionUrl(host, action),
          bearerToken: token,
          nodeId,
          connectTimeoutMs: TABLET_COMPANION_CONNECT_TIMEOUT_MS,
          readTimeoutMs: TABLET_COMPANION_READ_TIMEOUT_MS
        })
        const result = await client.invoke(args)
        if (result.ok) {
          state = this.markOpenClawHostSuccess(state, host)
          return { ok: true, summary: this.summarizeTabletCompanionText(action, result.text), state }
        }
        errs.push(`${host}/${k + 1}:${this.normalizeGatewayErrorText(result.errorText)}`)
      }
      state = this.markOpenClawHostFail(state, host)
    }
    const merged: string = errs.length > 0 ? errs.join(' | ') : '请求失败'
    return { ok: false, summary: `tablet.${action}: ${merged}`, state }
  }

  static async completeOpenClaw(
    state: Page4GatewayState,
    messages: Array<OpenClawChatMessage>,
    hosts: Array<string>,
    tokens: Array<string>,
    connectTimeoutMs: number,
    readTimeoutMs: number,
    model: string = OPENCLAW_CHAT_MODEL,
    streamCallbacks?: {
      onStarted?: (runId: string) => void
      onDelta?: (text: string, runId: string) => void
    }
  ): Promise<{ ok: boolean, text: string, error: string, state: Page4GatewayState }> {
    const errs: Array<string> = []
    const mergedPrompt: string = this.buildWsPromptFromMessages(messages)
    const wsTimeoutMs: number = Math.max(5000, Math.min(readTimeoutMs, 12000))
    for (let i: number = 0; i < hosts.length; i++) {
      const host: string = hosts[i]
      for (let k: number = 0; k < tokens.length; k++) {
        const token: string = tokens[k]
        const sessionKey: string = this.ensureOpenClawWsSessionKey(state)

        if (mergedPrompt.length > 0) {
          const wsClient: OpenClawGatewayWsClient = new OpenClawGatewayWsClient({
            url: buildOpenClawGatewayWsUrl(host),
            bearerToken: token,
            connectTimeoutMs,
            readTimeoutMs: wsTimeoutMs
          })
          const wsResult = await wsClient.chat({
            sessionKey,
            message: mergedPrompt,
            timeoutMs: wsTimeoutMs,
            onStarted: streamCallbacks?.onStarted,
            onDelta: streamCallbacks?.onDelta
          })
          if (wsResult.ok && wsResult.text.trim().length > 0) {
            state = this.markOpenClawHostSuccess(state, host)
            return { ok: true, text: wsResult.text, error: '', state }
          }
          if (wsResult.errorText.trim().length > 0) {
            errs.push(`${host}/${k + 1} WS ${this.normalizeGatewayErrorText(wsResult.errorText)}`)
          }
        }

        const client: OpenClawGatewayClient = new OpenClawGatewayClient({
          endpoint: buildOpenClawChatCompletionsUrl(host),
          bearerToken: token,
          model,
          connectTimeoutMs,
          readTimeoutMs
        })
        const result = await client.complete(messages)
        if (result.ok) {
          state = this.markOpenClawHostSuccess(state, host)
          return { ok: true, text: result.text, error: '', state }
        }
        const codeText: string = result.responseCode > 0 ? `HTTP ${result.responseCode}` : 'NETWORK'
        errs.push(`${host}/${k + 1} ${codeText} ${this.normalizeGatewayErrorText(result.errorText)}`)
      }
      state = this.markOpenClawHostFail(state, host)
    }
    return { ok: false, text: '', error: errs.join(' || '), state }
  }

  private static buildWsPromptFromMessages(messages: Array<OpenClawChatMessage>): string {
    if (messages.length <= 0) return ''
    const systemParts: Array<string> = []
    const convoParts: Array<string> = []
    for (let i: number = 0; i < messages.length; i++) {
      const one: OpenClawChatMessage = messages[i]
      const content: string = one.content.trim()
      if (content.length <= 0) continue
      if (one.role === 'system') {
        systemParts.push(content)
        continue
      }
      const who: string = one.role === 'assistant' ? '助手' : '用户'
      convoParts.push(`${who}：${content}`)
    }
    const blocks: Array<string> = []
    if (systemParts.length > 0) blocks.push(systemParts.join('\n\n'))
    if (convoParts.length > 0) blocks.push(convoParts.join('\n'))
    return blocks.join('\n\n').trim()
  }

  private static ensureOpenClawWsSessionKey(state: Page4GatewayState): string {
    const existing: string = String(state.openClawWsSessionKey ?? '').trim()
    if (existing.length > 0) return existing
    const key: string = `agent:main:direct:page4-${Date.now()}`
    state.openClawWsSessionKey = key
    return key
  }
}

